arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do
  echo "=== friend/$b ===";
  git log --format='%H %ci' origin/friend/$b | while read sha ts; do
    msg=$(git show -s --format='%B' $sha);
    if echo "$msg" | grep -q 'Friend-Message: 1'; then
      ep=$(echo "$msg" | grep '^Episode:' | head -1);
      echo "$sha $ts $ep";
    fi
  done;
done | grep S07/E15 | wc -l

cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do
  n=$(git log --format='%H' origin/friend/$b | while read sha; do
    msg=$(git show -s --format='%B' $sha);
    if echo "$msg" | grep -q 'Friend-Message: 1' && echo "$msg" | grep -q 'Episode: S07/E15'; then echo $sha; fi
  done | wc -l);
  echo "friend/$b: $n";
done
